function M({registerIndicator:f,sourceValues:h,nulls:y}){const u=(t,a)=>{const c=Math.max(1,Math.floor(a)),s=new Array(c).fill(NaN),b=new Array(t.length).fill(NaN);let l=0,n=0,i=0;for(let o=0;o<t.length;o++){const r=s[l];Number.isFinite(r)?n-=r:i+=1;const m=Number.isFinite(t[o])?t[o]:0;n+=m,s[l]=m,l=(l+1)%c,b[o]=n/Math.max(1,i)}return b};f({id:"oa-bbi",name:"Bulls Bears Index (BBI)",category:"Oscillators",placement:"onchart",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"p1",type:"number",label:"Period 1 (Ultra-Short)",default:3,min:1,max:5e3,step:1},{key:"p2",type:"number",label:"Period 2 (Short)",default:6,min:1,max:5e3,step:1},{key:"p3",type:"number",label:"Period 3 (Medium)",default:12,min:1,max:5e3,step:1},{key:"p4",type:"number",label:"Period 4 (Long)",default:24,min:1,max:5e3,step:1}],plots:[{key:"bbi",type:"line",title:"BBI",style:{color:"#ffeb3b",lineWidth:2}}],calc(t,a){const c=Math.max(1,Math.min(5e3,Math.floor(Number(a.p1)||3))),s=Math.max(1,Math.min(5e3,Math.floor(Number(a.p2)||6))),b=Math.max(1,Math.min(5e3,Math.floor(Number(a.p3)||12))),l=Math.max(1,Math.min(5e3,Math.floor(Number(a.p4)||24))),n=h(t,a.source??"close"),i=u(n,c),o=u(n,s),r=u(n,b),m=u(n,l),p=new Array(t.length).fill(NaN);for(let e=0;e<t.length;e++)!Number.isFinite(i[e])||!Number.isFinite(o[e])||!Number.isFinite(r[e])||!Number.isFinite(m[e])||(p[e]=(i[e]+o[e]+r[e]+m[e])/4);return{bbi:y(p)}}})}export{M as default};
